body{font-family:DejaVu Sans,Arial,sans-serif;color:#1e293b;font-size:11px;line-height:1.5;margin:24px}header{border-bottom:3px solid #009b7e;padding-bottom:16px;margin-bottom:24px}h1{font-size:24px;margin:6px 0}h2{font-size:17px;margin:20px 0 8px}h3{font-size:13px}.eyebrow{color:#007f67;font-weight:bold;letter-spacing:2px}.identity{margin-bottom:20px}.summary{width:100%;border-collapse:collapse;margin:16px 0 30px}.summary th,.summary td{padding:9px 12px;border-bottom:1px solid #e2e8f0;text-align:left}.summary td{text-align:right}.total{background:#d5f4ef;font-size:16px}.tasks{width:100%;border-collapse:collapse;table-layout:fixed}.tasks th,.tasks td{border:1px solid #e2e8f0;padding:7px;text-align:right;word-wrap:break-word}.tasks th{background:#f1f5f9;font-size:9px}.tasks th:first-child,.tasks td:first-child{text-align:left;width:48%}small{font-size:8px;color:#64748b}.day{margin-bottom:22px}.tasks tr{page-break-inside:avoid}.evidence{max-width:100%;max-height:620px;margin:12px 0;page-break-inside:avoid}.note{background:#fffbeb;padding:12px;color:#854d0e}footer{border-top:1px solid #e2e8f0;margin-top:30px;padding-top:12px;font-size:9px;color:#64748b}.toolbar{display:flex;gap:12px;margin-bottom:24px}.toolbar a,.toolbar button{padding:10px 16px;background:#007f67;color:white;border:0;border-radius:8px;text-decoration:none;cursor:pointer}@media print{.toolbar{display:none}body{margin:0}}
